import json
from collections import defaultdict
from pathlib import Path

import openpyxl
import pdfplumber

PDF = Path('/root/employees_backup.pdf')
XLSX = Path('/root/employees_current.xlsx')
OUTPUT = Path('/root/diff_report.json')
FIELDS = ['ID', 'First', 'Last', 'Dept', 'Position', 'Salary', 'Years', 'Location', 'Score']
NUMERIC = {'Salary', 'Years', 'Score'}


def extract_old():
    records = {}
    with pdfplumber.open(PDF) as pdf:
        for page_number, page in enumerate(pdf.pages, 1):
            rows = defaultdict(list)
            for word in page.extract_words():
                rows[round(word['top'], 1)].append(word)
            for words in rows.values():
                words.sort(key=lambda word: word['x0'])
                if not words or not words[0]['text'].startswith('EMP'):
                    continue
                columns = [[] for _ in FIELDS]
                for word in words:
                    x = word['x0']
                    if x < 105:
                        index = 0
                    elif x < 150:
                        index = 1
                    elif x < 205:
                        index = 2
                    elif x < 255:
                        index = 3
                    elif x < 325:
                        index = 4
                    elif x < 370:
                        index = 5
                    elif x < 398:
                        index = 6
                    elif x < 460:
                        index = 7
                    else:
                        index = 8
                    columns[index].append(word['text'])
                values = [' '.join(column) for column in columns]
                record = dict(zip(FIELDS, values))
                employee_id = record['ID']
                if employee_id in records:
                    raise ValueError(f'Duplicate PDF employee ID {employee_id}')
                try:
                    record['Salary'] = int(record['Salary'].replace(',', ''))
                    record['Years'] = int(record['Years'])
                    record['Score'] = float(record['Score'])
                except ValueError as exc:
                    raise ValueError(f'Bad numeric value on PDF page {page_number}: {record}') from exc
                records[employee_id] = record
    return records


def extract_current():
    workbook = openpyxl.load_workbook(XLSX, read_only=True, data_only=True)
    sheet = workbook['Employees']
    rows = sheet.iter_rows(values_only=True)
    headers = list(next(rows))
    if headers != FIELDS:
        raise ValueError(f'Unexpected spreadsheet fields: {headers}')
    records = {}
    for values in rows:
        if all(value is None for value in values):
            continue
        record = dict(zip(headers, values))
        employee_id = record['ID']
        if employee_id in records:
            raise ValueError(f'Duplicate spreadsheet employee ID {employee_id}')
        records[employee_id] = record
    workbook.close()
    return records


def main():
    old = extract_old()
    current = extract_current()
    deleted = sorted(set(old) - set(current))
    modified = []
    for employee_id in sorted(set(old) & set(current)):
        for field in FIELDS[1:]:
            old_value = old[employee_id][field]
            new_value = current[employee_id][field]
            if old_value != new_value:
                modified.append({
                    'id': employee_id,
                    'field': field,
                    'old_value': old_value,
                    'new_value': new_value,
                })
    report = {'deleted_employees': deleted, 'modified_employees': modified}
    OUTPUT.write_text(json.dumps(report, indent=2) + '\n', encoding='utf-8')
    print(f'PDF records: {len(old)}; spreadsheet records: {len(current)}')
    print(f'Deleted: {len(deleted)}; modified fields: {len(modified)}')
    print(f'Current-only employees (not requested): {len(set(current) - set(old))}')


if __name__ == '__main__':
    main()

